<?php
namespace Tests\Feature;
use App\Models\ComplianceSetting; use App\Models\Employee; use App\Models\GlAccountMapping; use App\Models\PayrollRun; use App\Models\Payslip; use App\Models\Tenant; use App\Services\GlExportService; use Illuminate\Support\Str; use Tests\TestCase;
class GlExportTest extends TestCase { public function test_approved_payroll_generates_balanced_gl_journal():void{if(config('database.default')!=='mysql')$this->markTestSkipped('Requires MySQL.');$tenant=Tenant::create(['name'=>'GL '.Str::random(5)]);try{tenancy()->initialize($tenant);$setting=ComplianceSetting::create(['version_label'=>'gl','effective_date'=>'2026-01-01','settings'=>[]]);foreach(GlExportService::REQUIRED as $i=>$key)GlAccountMapping::create(['key'=>$key,'account_code'=>(string)(5000+$i),'account_name'=>$key]);$e=Employee::create(['name'=>'E','national_id'=>'GL-'.Str::uuid(),'hire_date'=>'2026-01-01','salary'=>'500.000','status'=>'active']);$run=PayrollRun::create(['month'=>9,'year'=>2026,'status'=>'approved','compliance_setting_id'=>$setting->id,'locked_at'=>now()]);Payslip::create(['payroll_run_id'=>$run->id,'employee_id'=>$e->id,'gross_salary'=>'500.000','unpaid_absence_deduction'=>'20.000','overtime_pay'=>'30.000','earnings_total'=>'10.000','deductions_total'=>'15.000','loan_deductions_total'=>'25.000','ssc_employee'=>'30.000','ssc_employer'=>'60.000','income_tax'=>'5.000','surcharge'=>'0.000','net_salary'=>'445.000','calculation_snapshot'=>[]]);$j=app(GlExportService::class)->lines($run);$this->assertSame($j['total_debit'],$j['total_credit']);$this->assertSame('580.000',$j['total_debit']);}finally{if(tenancy()->initialized)tenancy()->end();$tenant->delete();}} }
